contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 dep, uint256 amt) public payable {
        require(dep > 0);
        require(amt > 0);
        c.deposit{value: dep}();
        uint256 contractBalBefore = address(c).balance;
        uint256 myBalBefore = address(this).balance;
        bool reverted;
        if (amt <= dep) {
            c.withdraw(amt);
            reverted = false;
        } else {
            try c.withdraw(amt) { reverted = false; }
            catch { reverted = true; }
        }
        if (!reverted) {
            assert(address(this).balance - myBalBefore == amt && address(c).balance == contractBalBefore - amt);
        } else {
            assert(address(this).balance == myBalBefore && address(c).balance == contractBalBefore);
        }
    }
    receive() external payable {}
}

